        acquired + tariff[0] - 1,
        acquired + tariff[0],
        complete - 1,
        complete,
    ] {
        DROPS.with(|n| n.set(0));
        let ((success, allocation), refused, paid, first) = with_limit_usage_refusal(limit, || {
            measure(|| {
                let mut b = ReplayBudget::new();
