                        drop(e);
                        return false;
                    }
                };
                receiver.insert_owned(&f, &mut incoming, State([1; 50]), &mut b);
                if !receiver.failed {
                    let value = incoming.into_one().next().unwrap();
                    let pointer = std::ptr::from_ref(value.as_ref());
